wire [3:0] d;     // 4 位总线
reg  [1:0] y;     // 2 位 reg 变量

assign d = 4'b0101;
// 4'b0101 : 4 位，二进制，值 0101
// 8'hA7   : 8 位，十六进制，值 A7
// 1'b1    : 1 位，二进制，值 1

module mux2_1(
    input a,
    input b,
    input sel,
    output y
);
assign y = sel ? b : a;
endmodule

module mux4_1(
    input [3:0] d,
    input [1:0] sel,
    output reg y
);
always @(*) begin
    case(sel)
        2'b00: y = d[0];
        2'b01: y = d[1];
        2'b10: y = d[2];
        2'b11: y = d[3];
    endcase
end
endmodule

module decoder2_4(
    input [1:0] a,
    output reg [3:0] y
);
always @(*) begin
    case(a)
        2'b00: y = 4'b0001;
        2'b01: y = 4'b0010;
        2'b10: y = 4'b0100;
        2'b11: y = 4'b1000;
    endcase
end
endmodule

