module dff(
    input clk,
    input rst_n,
    input d,
    output reg q
);
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        q <= 1'b0;
    else
        q <= d;
end
endmodule

module dff_en(
    input clk,
    input rst_n,
    input en,
    input d,
    output reg q
);
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        q <= 1'b0;
    else if(en)
        q <= d;
end
endmodule

