module counter4(
    input clk,
    input rst_n,
    output reg [3:0] cnt
);
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        cnt <= 4'b0000;
    else
        cnt <= cnt + 1'b1;
end
endmodule

module shift_reg(
    input clk,
    input rst_n,
    input d,
    output reg [3:0] q
);
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        q <= 4'b0000;
    else
        q <= {q[2:0], d};
end
endmodule

