module top_module(
    input a,
    input b,
    input sel,
    output y
);
wire w1;
and_gate u1(
    .a(a),
    .b(b),
    .y(w1)
);
mux2_1 u2(
    .a(w1),
    .b(a),
    .sel(sel),
    .y(y)
);
endmodule

module counter #(
    parameter WIDTH = 8
)(
    input clk,
    input rst_n,
    output reg [WIDTH-1:0] cnt
);
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        cnt <= 0;
    else
        cnt <= cnt + 1'b1;
end
endmodule

counter #(8)  u1(...);  // 8 位计数器
counter #(16) u2(...);  // 16 位计数器

module ram(
    input clk,
    input we,
    input [3:0] addr,
    input [7:0] din,
    output reg [7:0] dout
);
reg [7:0] mem [15:0];
always @(posedge clk) begin
    if(we)
        mem[addr] <= din;
    dout <= mem[addr];
end
endmodule

